edits.old:
    if (!tempFile.setExecutable(false))
    {
        IO.logger.log(Level.WARNING, "Could not set Executable permissions");
    }
}

edits.new:
    if (!tempFile.setExecutable(false))
    {
        IO.logger.log(Level.WARNING, "Could not set Executable permissions");
    }
    if (!tempFile.delete())
    {
        IO.logger.log(Level.WARNING, "Could not delete temporary file");
    }
}
